DATA = {
    "products": ["graph", "music"],
    "machines": ["printing", "scanning"],
    "profit": {"graph": 4.0, "music": 2.5},
    # minutes per ream on each machine
    "time": {
        ("printing", "graph"): 3.0,
        ("printing", "music"): 1.5,
        ("scanning", "graph"): 5.5,
        ("scanning", "music"): 3.0,
    },
    # maximum minutes available per machine per day
    "availability": {"printing": 350.0, "scanning": 350.0},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.M = pyo.Set(initialize=d["machines"])

    # Decision: reams produced per day (continuous, nonnegative)
    model.production = pyo.Var(
        model.P, domain=pyo.NonNegativeReals, bounds=(0, None)
    )

    # Objective: maximize total daily profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Machine capacity constraints (one per machine)
    def capacity_rule(m, mach):
        return sum(
            d["time"][(mach, p)] * m.production[p] for p in m.P
        ) <= d["availability"][mach]

    model.capacity = pyo.Constraint(model.M, rule=capacity_rule)

    return model


