import pyomo.environ as pyo

DATA = {
    "products": ["graph", "music"],
    "machines": ["printing", "scanning"],
    # minutes of machine r per ream of product p
    "usage": {
        ("printing", "graph"): 3.0,
        ("printing", "music"): 1.5,
        ("scanning", "graph"): 5.5,
        ("scanning", "music"): 3.0,
    },
    # minutes available per machine per day
    "capacity": {
        "printing": 350.0,
        "scanning": 350.0,
    },
    # profit per package (= per ream) of each product
    "profit": {
        "graph": 4.0,
        "music": 2.5,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["machines"])

    # Decision variables: reams produced per day
    model.production = pyo.Var(model.P, domain=pyo.NonNegativeReals)

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraints: one per machine, capacity limit
    def machine_capacity_rule(m, r):
        return sum(d["usage"][(r, p)] * m.production[p] for p in m.P) <= d["capacity"][r]

    model.machine_capacity = pyo.Constraint(model.R, rule=machine_capacity_rule)

    return model


